//! Original LX7 MMIO guests for the four exact camera SKUs. No UVC/factory claim.
use emu_core::{Bus,Core};
use esp_soc::{SocBus,Stop,picture::{Picture,Jpeg,JpegError}};
const PC:u32=0x40370000;const GPIO:u32=0x60004000;const LCD:u32=0x60041000;const DESC:u32=0x3fc88000;const DATA:u32=0x3fc90000;const PERIOD:u64=24_000_000;
const BOARDS:[(&str,bool);4]=[("atoms3r-cam",false),("atoms3r-cam-chatbot",false),("atoms3r-m12",true),("atoms3r-m12-volcengine",true)];
struct Guest{m:esp32s3::Machine,ov:bool}
impl Guest {
    fn new(name:&str,ov:bool)->Self {let mut m=esp32s3::machine([0;6]);m.bus.board=esp32s3::board::make_board(name).unwrap();m.bus.attach_board_devices();m.bus.set_flash_size(8<<20);m.bus.set_psram_size(8<<20).unwrap();let mut g=Self{m,ov};g.program();g}
    fn program(&mut self){self.m.bus.load_bytes(PC,&[0x32,0x64,0,0x52,0x24,0]).unwrap();self.m.cores[0].ps=0;self.m.cores[0].set_jit(false);}
    fn put(&mut self,a:u32,v:u32){self.m.cores[0].pc=PC;self.m.cores[0].set_ar(4,a);self.m.cores[0].set_ar(3,v);assert!(matches!(self.m.run(1),Stop::MaxInsns));}
    fn get(&mut self,a:u32)->u32{self.m.cores[0].pc=PC+3;self.m.cores[0].set_ar(4,a);assert!(matches!(self.m.run(1),Stop::MaxInsns));self.m.cores[0].get_ar(5)}
    fn route(&mut self,p:u8,s:u32){self.put(0x60009004+4*u32::from(p),1<<12|1<<9);self.put(GPIO+0x554+4*u32::from(p),s);if s==256{self.put(GPIO+if p<32{0x24}else{0x30},1<<(p%32));}}
    fn high(&mut self,p:u8,v:bool){self.put(GPIO+if p<32{if v{8}else{12}}else if v{20}else{24},1<<(p%32));}
    fn i2c_route(&mut self,b:u32,sda:u8,scl:u8){for(p,s)in[(sda,90+b*2),(scl,89+b*2)]{self.route(p,s);self.put(GPIO+0x154+4*s,0x80|u32::from(p));}}
    fn i2c(&mut self,b:usize,a:u8,bytes:&[u8],n:u8)->Option<Vec<u8>>{let base=[0x60013000,0x60027000][b];self.put(base+0x24,u32::MAX);self.put(base+0x18,3<<12);for v in[a<<1].into_iter().chain(bytes.iter().copied()){self.put(base+0x1c,u32::from(v));}let mut cmd=vec![6<<11,1<<11|1<<8|(bytes.len()+1)as u32];if n>0{self.put(base+0x1c,u32::from(a<<1|1));cmd.extend([6<<11,1<<11|1<<8|1,3<<11|u32::from(n)]);}cmd.push(2<<11);for(i,v)in cmd.into_iter().enumerate(){self.put(base+0x58+4*i as u32,v);}self.put(base+4,1<<5);self.m.bus.tick(100_000);if self.get(base+0x20)&(1<<10)!=0{return None;}assert_ne!(self.get(base+0x20)&(1<<7),0);Some((0..n).map(|_|self.get(base+0x1c)as u8).collect())}
    fn wr(&mut self,r:u16,v:u8){let bytes=if self.ov{vec![(r>>8)as u8,r as u8,v]}else{vec![r as u8,v]};let a=if self.ov{0x3c}else{0x21};assert_eq!(self.i2c(0,a,&bytes,0),Some(vec![]));}
    fn power(&mut self,on:bool){self.route(18,256);self.high(18,!on);}
    fn configure(&mut self){self.i2c_route(0,12,9);if self.ov{for(r,v)in[(0x3808,0),(0x3809,8),(0x380a,0),(0x380b,4),(0x4300,0x61),(0x3008,2)]{self.wr(r,v);}}else{for(r,v)in[(0xfe,1),(0x54,0x11),(0xfe,0),(0x25,15),(0x24,0xa6),(0x46,0x80),(0x49,0),(0x4a,4),(0x4b,0),(0x4c,8)]{self.wr(r,v);}}}
    fn dvp(&mut self){for(i,p)in[3,42,46,48,4,17,11,13,40,14,10].into_iter().enumerate(){self.route(p,256);self.put(GPIO+if p<32{0x28}else{0x34},1<<(p%32));let s=if i<8{133+i as u32}else{[149,150,152][i-8]};self.put(GPIO+0x154+4*s,0x80|u32::from(p));}self.route(21,149);self.put(0x600c001c,1<<8);self.put(LCD+4,3<<29|8<<9);self.put(LCD+0x64,1<<2);}
    fn frame(&mut self,len:usize)->Vec<u8>{self.put(LCD+8,0);self.put(0x6003f020,1<<21);self.put(0x6003f014,u32::MAX);self.m.bus.load_bytes(DATA,&vec![0xa5;len+4]).unwrap();for(i,v)in[1<<31|len as u32,DATA,0].into_iter().enumerate(){self.put(DESC+4*i as u32,v);}self.put(0x6003f004,1<<12);self.put(0x6003f048,5);self.put(0x6003f020,(DESC&0xfffff)|(1<<22));self.put(LCD+8,(1<<29)|(len as u32-1));self.m.bus.tick((PERIOD-self.m.bus.periph.lcd_cam.acc)as u32);self.m.bus.tick((PERIOD*11/20)as u32);(0..len).map(|i|self.m.bus.read8(DATA+i as u32).unwrap()).collect()}
    fn picture(&mut self,rgb:Vec<u8>){self.m.bus.board.set_camera_picture(Picture{w:1,h:1,rgb}).unwrap();}
}
#[test]
fn exact_sensor_ids_power_and_bmi_bus_are_independent(){for(name,ov)in BOARDS{let mut g=Guest::new(name,ov);g.i2c_route(0,12,9);let(a,reg,id)=if ov{(0x3c,vec![0x30,0x0a],0x36)}else{(0x21,vec![0],0x9b)};assert_eq!(g.i2c(0,a,&reg,1),None);g.power(true);assert_eq!(g.i2c(0,a,&reg,1),Some(vec![id]));assert_eq!(g.i2c(0,if ov{0x21}else{0x3c},&reg,1),None);g.i2c_route(1,45,0);assert_eq!(g.i2c(1,a,&reg,1),None);assert_eq!(g.i2c(1,0x68,&[0],1),Some(vec![0x24]));g.i2c_route(0,9,12);assert_eq!(g.i2c(0,a,&reg,1),None);g.i2c_route(0,12,9);g.power(false);assert_eq!(g.i2c(0,a,&reg,1),None);g.route(18,73);assert_eq!(g.i2c(0,a,&reg,1),None);}}
#[test]
fn four_camera_skus_copy_real_virtual_pixels_and_reject_clock_route_power_and_reboot(){for(name,ov)in BOARDS{let mut g=Guest::new(name,ov);g.power(true);g.configure();g.dvp();g.picture(vec![255,0,0]);assert_eq!(g.frame(64),[248,0].repeat(32),"{name}");g.picture(vec![0,255,0]);assert_eq!(g.frame(64),[7,224].repeat(32));g.put(GPIO+0x154+4*133,0x80|6);assert_eq!(g.frame(64),[0xa5;64]);g.put(GPIO+0x154+4*133,0x80|3);g.route(21,256);assert_eq!(g.frame(64),[0xa5;64]);g.route(21,149);g.power(false);assert_eq!(g.frame(64),[0xa5;64]);g.power(true);assert_eq!(g.frame(64),[0xa5;64]);g.configure();assert_eq!(g.frame(64),[7,224].repeat(32));
    if ov{g.wr(0x4300,0x10);}else{g.wr(0x24,0xb1);}assert_eq!(g.frame(32),[149;32]);
    g.m.reboot();g.program();assert_eq!(g.m.bus.board.camera_preview(1,1),Some(vec![0,255,0]));g.dvp();assert_eq!(g.frame(32),[0xa5;32]);g.power(true);g.configure();assert_eq!(g.frame(64),[7,224].repeat(32));}}
#[test]
fn only_ov3660_skus_accept_verbatim_jpeg_with_matching_sensor_size(){let bytes=vec![255,216,255,192,0,11,8,0,4,0,8,1,1,0x11,0,255,218,0,8,1,1,0,0,63,0,0x42,255,0,0x23,255,217];for(name,ov)in BOARDS{let mut g=Guest::new(name,ov);g.power(true);g.configure();g.dvp();let jpeg=Jpeg::parse(bytes.clone()).unwrap();if !ov{assert_eq!(g.m.bus.board.set_camera_jpeg(jpeg),Err(JpegError::Unsupported));continue;}g.wr(0x3821,0x20);assert_eq!(g.frame(bytes.len()),vec![0xa5;bytes.len()]);g.m.bus.board.set_camera_jpeg(jpeg).unwrap();assert_eq!(g.frame(bytes.len()),bytes);assert_eq!(g.m.bus.read8(DATA+bytes.len()as u32).unwrap(),0xa5);g.wr(0x3809,12);assert_eq!(g.frame(bytes.len()),vec![0xa5;bytes.len()]);}}
